import openpyxl
from openpyxl.utils import get_column_letter

wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']

# find cells containing 2019..2023
years={2019,2020,2021,2022,2023}
found=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if v in years:
            found.append((cell.coordinate,v))

print('Found year cells:', found)

# find header-like row that contains 2019 perhaps as string
found_str=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if isinstance(v,str) and v.strip() in {'2019','2020','2021','2022','2023'}:
            found_str.append((cell.coordinate,v))
print('Found year string cells:', found_str)

# print first 10 rows non-empty coordinates
max_col=ws.max_column
for r in range(1,31):
    row_non=[]
    for c in range(1,max_col+1):
        v=ws.cell(row=r,column=c).value
        if v not in (None,''):
            row_non.append(f"{get_column_letter(c)}{r}={v!r}")
    if row_non:
        print(f"Row {r} non-empty:")
        for item in row_non:
            print(' ',item)
